# Render creature atlas and animation reviews.
"""Portable animation review built from the same atlases and manifest the game reads."""
import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
import base64,html,io,json,shutil,sys
from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
from pixel_atlas import exact_png_bytes
ROOT=Path(__file__).resolve().parents[3];PACK=ROOT/'content/tactics/base';OUT=ROOT/'docs/art/creatures';OUT.mkdir(parents=True,exist_ok=True)
PRIMARY={'wolf':'beasts.wolf.grey','boar':'beasts.boar.brown','bear':'beasts.bear.brown','spider':'beasts.spider.black','slime':'beasts.slime.green','bat':'beasts.bat.dusk','drake':'beasts.drake.red','warg':'bestiary.warg.black','hookbeak':'bestiary.hookbeak.brown','scorpion':'bestiary.scorpion.sand','harpy':'bestiary.harpy.dusk','wisp':'bestiary.wisp.marsh','gargoyle':'bestiary.gargoyle.granite','crab':'bestiary.crab.shore','mule':'fauna.pack_mule','goat':'fauna.farm_goat','fox':'fauna.red_fox','duck':'fauna.river_duck','crow':'fauna.field_crow','dog':'fauna.farm_dog','sheep':'fauna.farm_sheep'}
NAMES={'spider':'Giant Spider','bat':'Giant Bat','scorpion':'Giant Scorpion','crab':'Giant Crab','mule':'Pack Mule','dog':'Farm Dog','sheep':'Farm Sheep','wisp':"Will-o’-Wisp"}
HERO=Image.open(PACK/'tactical/human_fighter.png').convert('RGBA').crop((0,0,160,160))
FONT=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',16);SMALL=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',12)
def uri(data,mime):return 'data:'+mime+';base64,'+base64.b64encode(data).decode()
def frame(c,column,row):
 w,h=c['frame']['width'],c['frame']['height'];x=column%c['columns']*w;y=(row*c['rowsPerDirection']+column//c['columns'])*h;return c['image'].crop((x,y,x+w,y+h))
def preview(c,column,row,zoom=None):
 z=c['zoom'] if zoom is None else zoom;im=frame(c,column,row);im=im.resize((round(im.width*z),round(im.height*z)),Image.Resampling.NEAREST);ax,ay=c['frame']['anchor'];canvas=Image.new('RGB',(400,320),'#202329');hero=HERO.resize((240,240),Image.Resampling.NEAREST);canvas.paste(hero,(-55,113),hero);canvas.paste(im,(250-round(ax*z),298-round(ay*z)),im);ImageDraw.Draw(canvas).line((12,299,388,299),fill='#505563');return canvas

def main():
 data=json.loads((PACK/'creatures/manifest.json').read_text());actors=[];cards=[];payload=[]
 for key,artkey in PRIMARY.items():
  found=next((c for c in data['sprites'].values() if artkey in c['keys']),None)
  if found is None:
   if '--partial' in sys.argv:continue
   raise SystemExit('Runtime sprite not ready: '+artkey)
  c={**found,'id':key,'name':NAMES.get(key,key.title()),'image':Image.open(PACK/'creatures'/found['file']).convert('RGBA')};ax,ay=c['frame']['anchor'];bbs=[frame(c,n,d).getbbox() for d in range(8) for n in c['anims']['walk']['frames']];c['zoom']=c['pixelScale']*3;actors.append(c)
  for action in ['idle','walk']:
   anim=c['anims'][action];fs=[preview(c,n,row) for row in range(8) for n in anim['frames']];target=OUT/(key+'-'+action+'.gif');fs[0].save(target,save_all=True,append_images=fs[1:],duration=round(1000/anim['fps']/10)*10,loop=0,disposal=2)
  raw=(OUT/(key+'-walk.gif')).read_bytes();cards.append('<article><h2>'+html.escape(c['name'])+'</h2><p>'+'3× game scale · human at left · eight directions</p><img width="400" height="320" alt="'+html.escape(c['name']+' walking in eight directions')+'" src="'+uri(raw,'image/gif')+'"><canvas width="400" height="320" hidden></canvas></article>');payload.append({k:v for k,v in c.items() if k!='image'}|{'atlas':uri(exact_png_bytes(c['image']),'image/png')})
 dirs=data['directions'];hero=Image.open(PACK/'tactical/human_fighter.png').convert('RGBA').crop((0,0,160,160));hero_anchor=(80,123)
 def board(d,f,action):
  cw,ch=324,232;page=Image.new('RGB',(cw*4,ch*6+64),'#202329');draw=ImageDraw.Draw(page);draw.text((14,10),'WARDENFLAME · '+str(len(actors))+' CREATURE & ANIMAL FAMILIES',font=FONT,fill='#eee4cd');draw.text((14,36),'Common game scale, enlarged 2× · '+action+' · facing '+dirs[d],font=SMALL,fill='#b7c0ca')
  for i,c in enumerate(actors):
   x=i%4*cw;y=i//4*ch+64;draw.text((x+10,y+6),c['name'],font=FONT,fill='#eee4cd');anim=c['anims'][action];im=frame(c,anim['frames'][f%len(anim['frames'])],d);z=c['pixelScale']*2
   if z!=1:im=im.resize((round(im.width*z),round(im.height*z)),Image.Resampling.NEAREST)
   ax,ay=c['frame']['anchor'];page.paste(im,(x+cw//2-round(ax*z),y+ch-22-round(ay*z)),im);draw.line((x+8,y+ch-21,x+cw-8,y+ch-21),fill='#505563')
  i=len(actors);x=i%4*cw;y=i//4*ch+64;draw.text((x+10,y+6),'Human fighter · scale reference',font=FONT,fill='#eee4cd');page.paste(hero,(x+cw//2-hero_anchor[0],y+ch-22-hero_anchor[1]),hero);return page
 for action,n,ms in [('idle',4,180),('walk',8,110)]:
  fs=[board(d,f,action).quantize(colors=256) for d in range(8) for f in range(n)];fs[0].save(OUT/('all-'+action+'.gif'),save_all=True,append_images=fs[1:],duration=ms,loop=0,disposal=2)
 board(7,0,'walk').save(OUT/'scale-review.png')
 template='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Wardenflame — Creature & Animal Animations</title><style>body{margin:clamp(1rem,3vw,2rem);background:#202329;color:#eee4cd;font:16px system-ui}p{color:#bbc3cc;line-height:1.5}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(340px,100%),1fr));gap:1rem}article{background:#282e35;padding:1rem;min-width:0}h2{font-size:19px}img,canvas{width:100%;height:auto;image-rendering:pixelated}button,select{padding:.6rem;background:#333b45;color:#eee4cd;border:1px solid #626e7e;margin:.25rem;cursor:pointer}.controls{position:sticky;top:0;background:#202329;padding:.5rem;z-index:1}small{color:#bbc3cc}[hidden]{display:none!important}</style><h1>Wardenflame · Creature & Animal Animations</h1><p>All previews are embedded in this file. Images animate without a server or JavaScript. These are the same pixel atlases the game reads. The initial previews cycle through all eight directions.</p><div class="controls"><label>Direction <select id="direction"><option value="auto">Auto-turn</option>OPTIONS</select></label><label>Animation <select id="action"><option value="walk">Movement</option><option value="idle">Idle</option><option value="attack">Basic attack</option><option value="down">Defeated</option></select></label><button id="inspect">Inspect selected view</button><button id="pause">Pause inspection</button><button id="gifs">Show automatic previews</button><p id="status">Choose a direction and inspect it, or watch the automatic previews below.</p></div><main>CARDS</main><p>Every card uses the same 3× game magnification, including its human reference. The game uses these relative sizes and fixed ground anchors. Everyday animals have no new combat stats; they idle when a combat-only animation is selected. Distinct special forms such as the mounted warg retain their existing art.</p><script>const data=PAYLOAD,dirs=DIRECTIONS,hero=new Image;hero.src=HERO_IMAGE;let interactive=false,paused=false,clock=0,last=performance.now();const actors=[...document.querySelectorAll('article')].map((el,i)=>{const im=new Image;im.src=data[i].atlas;return {c:data[i],image:im,el,ctx:el.querySelector('canvas').getContext('2d')}});function inspect(){interactive=true;actors.forEach(a=>{a.el.querySelector('img').hidden=true;a.el.querySelector('canvas').hidden=false})}document.querySelector('#inspect').onclick=inspect;document.querySelector('#direction').onchange=inspect;document.querySelector('#action').onchange=()=>{clock=0;inspect()};document.querySelector('#pause').onclick=e=>{inspect();paused=!paused;e.target.textContent=paused?'Play inspection':'Pause inspection'};document.querySelector('#gifs').onclick=()=>{interactive=false;actors.forEach(a=>{a.el.querySelector('img').hidden=false;a.el.querySelector('canvas').hidden=true})};function draw(t){if(!paused)clock+=t-last;last=t;if(interactive){const selected=document.querySelector('#direction').value,action=document.querySelector('#action').value;const direction=selected==='auto'?Math.floor(clock/1800)%8:Number(selected);document.querySelector('#status').textContent='Facing '+dirs[direction]+' · '+action;for(const {c,image,ctx} of actors){ctx.imageSmoothingEnabled=false;ctx.fillStyle='#202329';ctx.fillRect(0,0,400,320);const anim=c.anims[action]||c.anims.idle,step=Math.floor(clock*anim.fps/1000),n=anim.frames[anim.loop?step%anim.frames.length:Math.min(step,anim.frames.length-1)];const w=c.frame.width,h=c.frame.height,sx=n%c.columns*w,sy=(direction*c.rowsPerDirection+Math.floor(n/c.columns))*h,z=c.zoom;if(hero.complete&&hero.naturalWidth)ctx.drawImage(hero,-55,113,240,240);if(image.complete&&image.naturalWidth)ctx.drawImage(image,sx,sy,w,h,250-c.frame.anchor[0]*z,298-c.frame.anchor[1]*z,w*z,h*z);ctx.strokeStyle='#505563';ctx.beginPath();ctx.moveTo(12,299);ctx.lineTo(388,299);ctx.stroke()}}requestAnimationFrame(draw)}requestAnimationFrame(draw)</script></html>'''
 options=''.join('<option value="'+str(i)+'">'+html.escape(d)+'</option>' for i,d in enumerate(dirs));page=template.replace('OPTIONS',options).replace('CARDS',''.join(cards)).replace('PAYLOAD',json.dumps(payload)).replace('DIRECTIONS',json.dumps(dirs)).replace('HERO_IMAGE',json.dumps(uri(exact_png_bytes(HERO),'image/png')));(OUT/'index.html').write_text(page);shutil.copyfile(OUT/'index.html','/workspace/Wardenflame-All-Creatures.html');print('Built',len(actors),'embedded previews and atlas inspector;',len(page.encode()),'HTML bytes.')
if __name__=='__main__':main()
